import{state,setState}from"./state.js";import{updateChildSettings,getChildLink,regenerateChildToken}from"./api.js";import{renderAll}from"./ui.js";import{showToast,showConfirm}from"./utils.js";function getTargetChildId(){return state.currentChildId||state.children[0]?.id||null}function applyPayloadToState(t,e){const i=state.children.find(t=>t.id==e);i&&(t.name&&(i.name=t.name),void 0!==t.monthlyLimit&&(i.monthlyLimit=t.monthlyLimit),void 0!==t.dailyCoinLimit&&(i.dailyCoinLimit=t.dailyCoinLimit));const n={};void 0!==t.monthlyLimit&&(n.monthlyLimit=t.monthlyLimit),void 0!==t.dailyCoinLimit&&(n.dailyCoinLimit=t.dailyCoinLimit),Object.keys(n).length&&setState(n)}async function persistChildSettings(t){const e=getTargetChildId();if(!e)return showToast("Сначала добавьте ребенка","error");const i=await updateChildSettings(state.familyId,e,t);return i?.success&&applyPayloadToState(t,e),i}export async function saveChildProfileInline(){const t=document.getElementById("settings-child-name-inline")?.value.trim();if(!t)return showToast("Введите имя ребенка","error");try{const e=await persistChildSettings({name:t});if(!e?.success)throw new Error(e?.error||"Ошибка обновления");showToast("Информация обновлена","success"),renderAll()}catch(t){showToast(t.message,"error")}}function parseLimitValue(t,e){if(!t)return null;const i=t.value?.trim();if(!i)return null;const n=parseInt(i,10);if(Number.isNaN(n)||n<0)throw new Error(`Некорректный лимит ${e}`);return n}export async function saveChildLimitsInline(){const t=document.getElementById("settings-child-monthly-limit-inline"),e=document.getElementById("settings-child-day-coin-limit-inline"),i={};try{const n=parseLimitValue(t,"денег");null!==n&&(i.monthlyLimit=n);const s=parseLimitValue(e,"монет");if(null!==s&&(i.dailyCoinLimit=s),!Object.keys(i).length)return showToast("Укажите хотя бы один лимит","error");const o=await persistChildSettings(i);if(!o?.success)throw new Error(o?.error||"Ошибка сохранения лимитов");showToast("Лимиты сохранены","success"),renderAll()}catch(t){showToast(t.message,"error")}}export async function refreshChildLinkInline(){const t=document.getElementById("settings-child-link-input-inline");if(!t)return;const e=getTargetChildId();if(!e)return t.value="Сначала добавьте ребенка";try{const i=await getChildLink(e);i.link&&(t.value=i.link)}catch(t){console.error(t)}}export async function copyChildLinkInline(){const t=document.getElementById("settings-child-link-input-inline");if(t?.value){t.select();try{document.execCommand("copy"),showToast("Ссылка скопирована!","success");const t=document.getElementById("child-link-status");t&&(t.classList.remove("hidden"),setTimeout(()=>t.classList.add("hidden"),3e3))}catch(t){showToast("Не удалось скопировать","error")}}}export async function regenerateChildLinkInline(){if(!await showConfirm("Обновление ссылки","Вы уверены? Старая ссылка перестанет работать."))return;const t=getTargetChildId();if(!t)return showToast("Нет выбранного ребенка","error");try{const e=await regenerateChildToken(t);if(e.link){const t=document.getElementById("settings-child-link-input-inline");t&&(t.value=e.link),showToast("Ссылка обновлена","success")}else showToast("Ошибка при обновлении ссылки","error")}catch(t){showToast("Ошибка сети","error")}}